require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/admin.php';require_once __DIR__.'/../lib/crypto.php';send_cors_headers();$context=require_admin('events.manage');$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$stmt=$db->query('SELECT e.*,h.display_name AS host_name FROM events e JOIN event_hosts h ON h.id=e.host_id ORDER BY e.created_at DESC LIMIT 300');json_response(200,['success'=>true,'events'=>$stmt->fetchAll()]);}if($method==='POST'){$body=get_json_body();$action=trim((string)($body['action']??'create'));if($action==='create'){$title=trim((string)($body['title']??''));$description=trim((string)($body['description']??''));$start=strtotime((string)($body['starts_at']??''));$end=strtotime((string)($body['ends_at']??''));if(mb_strlen($title)<5||mb_strlen($description)<40||$start===false||$end===false||$end<=$start)json_response(422,['success'=>false,'message'=>'Event title, description and date range are invalid.']);$hostId=uuid_string();$eventId=uuid_string();$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/','-',strtolower($title)),'-')).'-'.substr($eventId,0,6);$db->beginTransaction();try{$db->prepare('INSERT INTO event_hosts (id,owner_type,owner_id,display_name,email,mobile,bio,verification_status,created_at) VALUES (:id,"admin",:owner,:name,:email,:mobile,:bio,"verified",UTC_TIMESTAMP())')->execute(['id'=>$hostId,'owner'=>$context['admin']['id'],'name'=>trim((string)($body['host_name']??$context['admin']['full_name'])),'email'=>strtolower(trim((string)($body['host_email']??$context['admin']['email']))),'mobile'=>preg_replace('/\D+/','',(string)($body['host_mobile']??'9999999999')),'bio'=>$body['host_bio']??null]);$db->prepare('INSERT INTO events (id,host_id,title,slug,event_type,short_description,description,venue_type,venue_name,address_json,online_url_encrypted,timezone,starts_at,ends_at,booking_opens_at,booking_closes_at,status,created_at,updated_at) VALUES (:id,:host,:title,:slug,:type,:short,:description,:venue_type,:venue_name,:address,:online_url,"Asia/Kolkata",:starts,:ends,:opens,:closes,"draft",UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['id'=>$eventId,'host'=>$hostId,'title'=>$title,'slug'=>$slug,'type'=>trim((string)($body['event_type']??'market')),'short'=>mb_substr(trim((string)($body['short_description']??$description)),0,500),'description'=>$description,'venue_type'=>in_array($body['venue_type']??'physical',['physical','online','hybrid'],true)?$body['venue_type']:'physical','venue_name'=>$body['venue_name']??null,'address'=>isset($body['address'])?json_encode($body['address']):null,'online_url'=>!empty($body['online_url'])?encrypt_sensitive((string)$body['online_url']):null,'starts'=>gmdate('Y-m-d H:i:s',$start),'ends'=>gmdate('Y-m-d H:i:s',$end),'opens'=>gmdate('Y-m-d H:i:s',strtotime((string)($body['booking_opens_at']??'now'))),'closes'=>gmdate('Y-m-d H:i:s',strtotime((string)($body['booking_closes_at']??$body['starts_at'])))]);foreach((array)($body['ticket_types']??[]) as $ticket){$capacity=max(1,(int)($ticket['capacity']??0));$db->prepare('INSERT INTO event_ticket_types (id,event_id,name,description,price,capacity,min_per_booking,max_per_booking,sales_start_at,sales_end_at,status,created_at) VALUES (:id,:event,:name,:description,:price,:capacity,1,:max,:starts,:ends,"active",UTC_TIMESTAMP())')->execute(['id'=>uuid_string(),'event'=>$eventId,'name'=>trim((string)($ticket['name']??'General')),'description'=>$ticket['description']??null,'price'=>max(0,(float)($ticket['price']??0)),'capacity'=>$capacity,'max'=>max(1,min(20,(int)($ticket['max_per_booking']??10))),'starts'=>gmdate('Y-m-d H:i:s',strtotime((string)($ticket['sales_start_at']??$body['booking_opens_at']??'now'))),'ends'=>gmdate('Y-m-d H:i:s',strtotime((string)($ticket['sales_end_at']??$body['booking_closes_at']??$body['starts_at'])))]);}$db->commit();json_response(201,['success'=>true,'message'=>'Event draft created.','event_id'=>$eventId]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}$id=trim((string)($body['event_id']??''));$next=['submit'=>'pending_review','approve'=>'published','request_changes'=>'changes_requested','cancel'=>'cancelled'][$action]??'';if($next==='')json_response(422,['success'=>false,'message'=>'Invalid event action.']);$stmt=$db->prepare('SELECT * FROM events WHERE id=:id');$stmt->execute(['id'=>$id]);$event=$stmt->fetch();if(!$event)json_response(404,['success'=>false,'message'=>'Event not found.']);$map=['draft'=>['pending_review','cancelled'],'pending_review'=>['published','changes_requested','cancelled'],'changes_requested'=>['pending_review','cancelled'],'published'=>['cancelled']];assert_transition($event['status'],$next,$map);$db->prepare('UPDATE events SET status=:status,review_notes=:notes,published_at=IF(:status="published",UTC_TIMESTAMP(),published_at),updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['status'=>$next,'notes'=>trim((string)($body['notes']??''))?:null,'id'=>$id]);record_status_change('event',$id,$event['status'],$next,$body['notes']??null);audit_event('admin.event_'.$action,'event',$id);json_response(200,['success'=>true,'message'=>'Event status updated.','status'=>$next]);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
